from pathlib import Path
import pandas as pd,json
base=Path('/app/dataset'); cal=json.load(open(base/'sensors_calibration.json'))['enterprise_platform']['deployment_environments']['system_config']['farms']
for letter in 'ABCDEFGHIJKLMNOPQRSTUVWX':
 fid='FARM_'+letter; p=base/f'production_{fid}.csv'; b=p.read_bytes(); enc='utf-16' if b.startswith(b'\xff\xfe') else 'utf-8'; tx=b.decode(enc); sep=';' if tx.splitlines()[3].count(';')>tx.splitlines()[3].count(',') else ','
 d=pd.read_csv(p,encoding=enc,sep=sep,skiprows=3,dtype=str,keep_default_na=False); tc=d.columns[0]; vc=cal[fid]['calibration_data']['value_column_name'];
 du=d[d[tc].duplicated(keep=False)]
 vals=[]
 for ts,g in du.groupby(tc,sort=False):
  x=g[vc].tolist()
  if len(set(x))>1 and any('888888.8' in v for v in x): vals.append((ts,x))
 print(fid, 'dup-injected',len(vals), 'orders', [('sentinel-last' if '888888.8'==x[-1].strip() else 'sentinel-first' if '888888.8' in [v.strip() for v in x] else 'other',x) for ts,x in vals[:2]])
PY",workdir:"/app",yield_time_ms:10000,max_output_tokens:4000}); text(r.output);
